CREATE TABLE IF NOT EXISTS family_state (id INTEGER PRIMARY KEY CHECK(id=1), revision INTEGER NOT NULL DEFAULT 0, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS family_photos (id TEXT PRIMARY KEY, name TEXT NOT NULL, data BLOB NOT NULL);
CREATE TABLE IF NOT EXISTS push_devices (id TEXT PRIMARY KEY, subscription TEXT NOT NULL, watches TEXT NOT NULL, expires INTEGER NOT NULL, state TEXT NOT NULL DEFAULT '{}', updated INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS push_health (id INTEGER PRIMARY KEY CHECK(id=1), last_run INTEGER, last_error TEXT);
CREATE TABLE IF NOT EXISTS push_lease (id INTEGER PRIMARY KEY CHECK(id=1), until_ms INTEGER NOT NULL DEFAULT 0);
INSERT OR IGNORE INTO push_lease(id,until_ms) VALUES(1,0);
